  "dup.title": "Is this already on UNIER?",
  "dup.text": "These petitions ask for something similar. Signing and sharing one of them keeps everyone together, which makes it harder to ignore. You can still start yours.",
  "kids.title": "Mylo's kids corner",
  "kids.nav": "Kids corner",
  "kids.hi": "Hi! I'm Mylo.",
  "kids.intro": "I'm a baby orange, and I live in the same world as you. Here you can read my story, colour me in, and see what people are asking for to make the world a little better.",
  "kids.feel.up": "Lots of people helped today. I feel great!",
  "kids.feel.down": "I'm a little worried today. Will you help me feel better?",
  "kids.feel.calm": "It's a quiet day. I'm happy you came by.",
  "kids.story": "Read my story",
  "kids.storyText": "A picture book to read together.",
  "kids.colour": "Colour me in",
  "kids.colourText": "Print the book and the colouring pages.",
  "kids.teachers": "For teachers",
  "kids.teachersText": "A lesson plan and worksheets for your class.",
  "kids.care": "What do you care about?",
  "kids.careText": "Pick the things that matter to you. Only this device remembers it.",
  "kids.asks": "What people are asking for",
  "kids.asksText": "Real petitions, told in simple words.",
  "kids.none": "Nothing here yet. Come back soon!",
  "kids.people": "{n} people already said yes",
  "kids.grownup": "Only grown-ups can sign. If you think this matters, show it to a grown-up you trust.",
  "kids.show": "Show a grown-up",
  "kids.do": "Small things you can do today",
  "kids.do1": "Tell a friend Mylo's story.",
  "kids.do2": "Switch off lights and taps you're not using.",
  "kids.do3": "Draw something you would change, and show it to someone.",
  "kids.do4": "Pick up litter, with a grown-up and gloves.",
  "kids.parents": "For grown-ups: this corner has no sign-up, no chat and no tracking. Children can read and explore; only adults sign petitions.",
  "p.easy": "In simple words",
  "p.easyKids": "More for kids in Mylo's kids corner",
  "teach.title": "Mylo in the classroom",
  "teach.lead": "A 45 minute lesson for ages 7 to 12 about speaking up together. Free to print and use.",
  "teach.goals": "What children learn",
  "teach.goal1": "What a petition is: many people asking for the same thing together.",
  "teach.goal2": "That problems in the world can be talked about calmly, and that small actions count.",
  "teach.goal3": "How to say clearly what they would change, and why.",
  "teach.plan": "Lesson plan",
  "teach.s1": "5 min · Meet Mylo. Show the picture book on the big screen and ask: how do you think Mylo feels?",
  "teach.s2": "10 min · Read the story together. Stop at page 4 and ask: what is a petition?",
  "teach.s3": "10 min · Worksheet 1, “What would you change?”. Each child draws and writes one thing.",
  "teach.s4": "15 min · Worksheet 2, “Our class petition”. In small groups, pick one idea and write who to ask, what to ask for and why.",
  "teach.s5": "5 min · Share. Groups read their petition aloud, and the class “signs” with a show of hands.",
  "teach.show": "Show the book on the big screen",
  "teach.print": "Print the worksheets",
  "teach.printBook": "Print the picture book",
  "teach.after": "Afterwards",
  "teach.afterText": "Send your class petition to the head teacher or the local council. Children never need an account on UNIER, and nothing here collects their data.",
  "teach.care": "A gentle note",
  "teach.careText": "Some topics can worry children. Keep the focus on what people can do together, and let them pick a topic that feels close to home.",
  "ws.title": "Worksheets",
  "ws.lead": "Two A4 worksheets. Print one of each per child or group.",
