  'don.orgText': "Giving as a company, foundation or group? Write to us first, so we can check the gift comes without conditions.",
  'don.share': "Share a petition",
  'don.start': "Start a petition",
  'don.startText': "Something needs to change? Start a petition and bring people together.",
  'don.startLink': "Start a petition",
  'don.faq': "Questions",
  'don.q1': "Can I get a tax receipt?",
  'don.a1': "Not at the moment. UNIER cannot give tax receipts yet. If that changes, this answer will say so.",
  'don.q2': "Can I stop a monthly gift?",
  'don.a2': "Yes, any time, with no questions. Use the link in your receipt email, or write to us and we stop it.",
  'don.q3': "Does giving give me a say in what happens on UNIER?",
  'don.a3': "No. A gift never changes what you see, which petitions rise, or how anything is reviewed. Everyone counts the same.",
  'don.q4': "What do you learn about me when I give?",
  'don.a4': "Only what a receipt needs, usually your name, email and the amount. The payment provider handles your card or bank details; UNIER never sees them, never links your gift to your signatures and never shares the list of donors.",
  'don.q5': "Where can I see how the money is spent?",
  'don.a5': "On the transparency page. It lists where money comes from and what it pays for, next to the live numbers on petitions and moderation.",
  'don.q6': "Do you take money from companies or political parties?",
  'don.a6': "We refuse any gift that comes with conditions. We do not take money from political parties, or from anyone a petition on UNIER is aimed at.",
