  "story.title": "Miért van Mylo csapdában?",
  "story.sub": "Rövid mese, amit bárkivel elolvashatsz, akár kisgyerekekkel is.",
  "story.read": "Elolvasom a mesét",
  "story.p1": "Ő Mylo. Egy kis narancs, és ugyanabban a világban él, mint te.",
  "story.p2": "Mylo nem tud elmenni a világunkból. Ha erdők égnek, a folyók piszkosak lesznek, vagy valakivel igazságtalanul bánnak, ő is megérzi.",
  "story.p3": "Túl kicsi ahhoz, hogy egyedül megoldja. A nagy döntéseket hozó felnőttek pedig nem mindig figyelnek oda.",
  "story.p4": "De ha sokan kérik együtt ugyanazt, azt nagyon nehéz figyelmen kívül hagyni. Ez a petíció: sok hang, ami egyet mond.",
  "story.p5": "Minden aláírással Mylo egy kicsit bátrabb lesz. Ha egy petíció nyer, új levelet növeszt.",
  "story.p6": "Mylo nem tud kijutni a világból. De együtt jobb hellyé tehetjük, ahol jó benne élni.",
