  'legal.englishOnly': "Rechtlich verbindlich ist dieser Text auf Englisch und Ungarisch. Eine Übersetzung in deine Sprache folgt.",
  "story.title": "Warum ist Mylo gefangen?",
  "story.sub": "Eine kurze Geschichte, die du mit allen lesen kannst, auch mit kleinen Kindern.",
  "story.read": "Geschichte lesen",
  "story.p1": "Das ist Mylo. Er ist eine kleine Orange und lebt in derselben Welt wie du.",
  "story.p2": "Mylo kann unsere Welt nicht verlassen. Wenn Wälder brennen, Flüsse schmutzig werden oder Menschen unfair behandelt werden, spürt er es auch.",
  "story.p3": "Er ist viel zu klein, um das allein zu ändern. Und die Erwachsenen, die die großen Entscheidungen treffen, hören nicht immer zu.",
  "story.p4": "Aber wenn viele Menschen gemeinsam um dasselbe bitten, kann man sie kaum überhören. Das ist eine Petition: viele Stimmen, die eines sagen.",
  "story.p5": "Jedes Mal, wenn jemand unterschreibt, wird Mylo ein bisschen mutiger. Wenn eine Petition gewinnt, wächst ihm ein neues Blatt.",
  "story.p6": "Mylo kommt aus der Welt nicht heraus. Aber gemeinsam können wir sie zu einem besseren Ort machen.",
