  "book.alt0": "Mylo, eine kleine lächelnde Orange, auf einem grünen Hügel mit einem Baum, einem Häuschen, einem Teich und der Sonne.",
  "book.alt1": "Ein grauer Himmel, brennende Bäume und Müll auf dem Boden. Mylo sieht krank aus.",
  "book.alt2": "Ein winziger, besorgter Mylo vor einem riesigen Gebäude mit hohen Säulen. In seiner Sprechblase stehen nur drei Punkte.",
  "book.alt3": "Mylo, voller Feuer, mitten in einer Menge mit Schildern voller Herzen, Häkchen und Blätter.",
  "book.alt4": "Mylo wird größer, neben einem Klemmbrett voller Häkchen, um ihn herum Sterne.",
  "book.alt5": "Mylo jubelt unter einem Regenbogen und einer aufgehenden Sonne, mit Menschen und Bäumen auf einer grünen Welt.",
