  "dup.title": "Gibt es das schon auf UNIER?",
  "dup.text": "Diese Petitionen fordern etwas Ähnliches. Wenn du eine davon unterschreibst und teilst, bleiben alle zusammen, und das ist schwerer zu ignorieren. Du kannst deine trotzdem starten.",
  "kids.title": "Mylos Kinderecke",
  "kids.nav": "Kinderecke",
  "kids.hi": "Hallo! Ich bin Mylo.",
  "kids.intro": "Ich bin eine kleine Orange und lebe in derselben Welt wie du. Hier kannst du meine Geschichte lesen, mich ausmalen und sehen, worum Menschen bitten, damit die Welt ein bisschen besser wird.",
  "kids.feel.up": "Heute haben ganz viele Menschen geholfen. Mir geht's super!",
  "kids.feel.down": "Ich mache mir heute ein bisschen Sorgen. Hilfst du mir, dass es mir besser geht?",
  "kids.feel.calm": "Heute ist ein ruhiger Tag. Schön, dass du da bist.",
  "kids.story": "Lies meine Geschichte",
  "kids.storyText": "Ein Bilderbuch zum gemeinsamen Lesen.",
  "kids.colour": "Mal mich aus",
  "kids.colourText": "Druck das Buch und die Ausmalbilder aus.",
  "kids.teachers": "Für Lehrkräfte",
  "kids.teachersText": "Ein Stundenplan und Arbeitsblätter für deine Klasse.",
  "kids.care": "Was ist dir wichtig?",
  "kids.careText": "Wähl aus, was dir wichtig ist. Nur dieses Gerät merkt es sich.",
  "kids.asks": "Worum Menschen bitten",
  "kids.asksText": "Echte Petitionen, in einfachen Worten erzählt.",
  "kids.none": "Hier ist noch nichts. Schau bald wieder vorbei!",
  "kids.people": "{n} Menschen haben schon Ja gesagt",
  "kids.grownup": "Nur Erwachsene können unterschreiben. Wenn du es wichtig findest, zeig es einem Erwachsenen, dem du vertraust.",
  "kids.show": "Zeig es einem Erwachsenen",
  "kids.do": "Kleine Dinge, die du heute tun kannst",
  "kids.do1": "Erzähl einem Freund oder einer Freundin Mylos Geschichte.",
  "kids.do2": "Mach Licht und Wasserhahn aus, wenn du sie nicht brauchst.",
  "kids.do3": "Mal etwas, das du ändern würdest, und zeig es jemandem.",
  "kids.do4": "Sammle Müll auf, mit einem Erwachsenen und Handschuhen.",
  "kids.parents": "Für Erwachsene: Hier gibt es keine Anmeldung, keinen Chat und kein Tracking. Kinder können lesen und entdecken; unterschreiben dürfen nur Erwachsene.",
  "p.easy": "In einfachen Worten",
  "p.easyKids": "Mehr für Kinder in Mylos Kinderecke",
  "teach.title": "Mylo im Klassenzimmer",
  "teach.lead": "Eine Unterrichtsstunde (45 Minuten) für 7- bis 12-Jährige darüber, gemeinsam die Stimme zu erheben. Kostenlos zum Ausdrucken und Nutzen.",
  "teach.goals": "Was die Kinder lernen",
  "teach.goal1": "Was eine Petition ist: Viele Menschen bitten gemeinsam um dasselbe.",
  "teach.goal2": "Dass man ruhig über Probleme in der Welt sprechen kann und dass kleine Taten zählen.",
  "teach.goal3": "Klar zu sagen, was sie ändern würden und warum.",
  "teach.plan": "Ablauf der Stunde",
  "teach.s1": "5 Min. · Mylo kennenlernen. Zeig das Bilderbuch an der Leinwand und frag: Wie fühlt sich Mylo wohl?",
  "teach.s2": "10 Min. · Die Geschichte gemeinsam lesen. Bei Seite 4 anhalten und fragen: Was ist eine Petition?",
  "teach.s3": "10 Min. · Arbeitsblatt 1, „Was würdest du ändern?“. Jedes Kind malt und schreibt eine Sache.",
  "teach.s4": "15 Min. · Arbeitsblatt 2, „Unsere Klassenpetition“. In kleinen Gruppen eine Idee wählen und aufschreiben: wen fragen wir, worum bitten wir und warum.",
  "teach.s5": "5 Min. · Vorstellen. Die Gruppen lesen ihre Petition vor, die Klasse „unterschreibt“ per Handzeichen.",
  "teach.show": "Buch auf der Leinwand zeigen",
  "teach.print": "Arbeitsblätter drucken",
  "teach.printBook": "Bilderbuch drucken",
  "teach.after": "Danach",
  "teach.afterText": "Schickt eure Klassenpetition an die Schulleitung oder die Gemeinde. Kinder brauchen nie ein Konto bei UNIER, und hier werden keine Daten über sie gesammelt.",
  "teach.care": "Ein kleiner Hinweis",
  "teach.careText": "Manche Themen können Kinder beunruhigen. Bleibt bei dem, was wir gemeinsam tun können, und lasst sie ein Thema aus ihrem Alltag wählen.",
