  'don.orgText': "Spendest du als Firma, Stiftung oder Gruppe? Schreib uns vorher, damit wir prüfen können, dass die Spende ohne Bedingungen kommt.",
  'don.share': "Teile eine Petition",
  'don.start': "Starte eine Petition",
  'don.startText': "Etwas muss sich ändern? Starte eine Petition und bring Menschen zusammen.",
  'don.startLink': "Petition starten",
  'don.faq': "Fragen",
  'don.q1': "Bekomme ich eine Spendenquittung für die Steuer?",
  'don.a1': "Im Moment nicht. UNIER kann noch keine Spendenquittungen ausstellen. Wenn sich das ändert, steht es hier.",
  'don.q2': "Kann ich eine monatliche Spende beenden?",
  'don.a2': "Ja, jederzeit und ohne Fragen. Nutze den Link in deiner Beleg-E-Mail oder schreib uns, dann beenden wir sie.",
  'don.q3': "Habe ich durch eine Spende mehr Einfluss auf UNIER?",
  'don.a3': "Nein. Eine Spende ändert nie, was du siehst, welche Petitionen aufsteigen oder wie etwas geprüft wird. Alle zählen gleich.",
  'don.q4': "Was erfahrt ihr über mich, wenn ich spende?",
  'don.a4': "Nur, was ein Beleg braucht, meist Name, E-Mail und Betrag. Karten- oder Bankdaten verarbeitet der Zahlungsanbieter; UNIER sieht sie nie, verknüpft deine Spende nie mit deinen Unterschriften und gibt die Liste der Spender nie weiter.",
  'don.q5': "Wo sehe ich, wofür das Geld ausgegeben wird?",
  'don.a5': "Auf der Transparenzseite. Dort steht, woher das Geld kommt und wofür es ausgegeben wird, neben den aktuellen Zahlen zu Petitionen und Moderation.",
  'don.q6': "Nehmt ihr Geld von Firmen oder Parteien?",
  'don.a6': "Wir lehnen jede Spende mit Bedingungen ab. Wir nehmen kein Geld von Parteien oder von jemandem, an den sich eine Petition auf UNIER richtet.",
  'don.askUs': "Noch eine Frage? Schreib uns:",
