  'legal.englishOnly': "Este texto es jurídicamente vinculante en inglés y húngaro. La traducción a tu idioma llegará pronto.",
  "story.title": "¿Por qué está atrapado Mylo?",
  "story.sub": "Una historia corta para leer con cualquiera, incluso con niños pequeños.",
  "story.read": "Leer la historia",
  "story.p1": "Este es Mylo. Es una naranja bebé y vive en el mismo mundo que tú.",
  "story.p2": "Mylo no puede salir de nuestro mundo. Cuando arden los bosques, se ensucian los ríos o se trata injustamente a la gente, él también lo siente.",
  "story.p3": "Es demasiado pequeño para arreglarlo solo. Y los mayores que toman las grandes decisiones no siempre escuchan.",
  "story.p4": "Pero cuando mucha gente pide lo mismo a la vez, es muy difícil ignorarla. Eso es una petición: muchas voces diciendo una sola cosa.",
  "story.p5": "Cada vez que alguien firma, Mylo se siente un poco más valiente. Cuando una petición gana, le crece una hoja nueva.",
  "story.p6": "Mylo no puede salir del mundo. Pero juntos podemos hacer de él un lugar mejor.",
