  "story.title": "Pourquoi Mylo est-il coincé ?",
  "story.sub": "Une petite histoire à lire avec tout le monde, même avec les tout-petits.",
  "story.read": "Lire l'histoire",
  "story.p1": "Voici Mylo. C'est un bébé orange, et il vit dans le même monde que toi.",
  "story.p2": "Mylo ne peut pas quitter notre monde. Quand les forêts brûlent, que les rivières se salissent ou que des gens sont traités injustement, il le ressent aussi.",
  "story.p3": "Il est bien trop petit pour tout réparer seul. Et les grandes personnes qui prennent les grandes décisions n'écoutent pas toujours.",
  "story.p4": "Mais quand beaucoup de gens demandent la même chose ensemble, c'est très difficile à ignorer. C'est ça, une pétition : beaucoup de voix qui disent une seule chose.",
  "story.p5": "Chaque fois que quelqu'un signe, Mylo se sent un peu plus courageux. Quand une pétition gagne, il lui pousse une nouvelle feuille.",
  "story.p6": "Mylo ne peut pas sortir du monde. Mais ensemble, nous pouvons en faire un endroit meilleur.",
  "story.next": "Suivant",
  "story.prev": "Retour",
  "story.again": "Relire",
