export * from './langs';
import { makeTFrom, type Lang } from './langs';
const DICTS: Record<Lang, Record<Key, string>> = { en, hu, de, es, fr };
export const messagesFor = (lang: Lang): Record<Key, string> => DICTS[lang] ?? en;
export function makeT(lang: Lang) { return makeTFrom(messagesFor(lang)); }
